include <tofino_eth_base.lcd>;  // uncomment to compile to Lucid (Tofino)\n\nmodule proto {\n  event req(uint32 i);\n  event resp(uint32 i, uint32 r);\n}\n\nmodule sender {\n  type t = { IntArray.t req_ct; IntArray.t resp_ct; port to_recv; };\n  comptime fun t create(port to_recv) {\n    return t { req_ct = IntArray.create(1); resp_ct = IntArray.create(1); to_recv = to_recv; };\n  }\n  fun void send_req(t self, uint32 i) {\n    IntArray.setm(self.req_ct, 0, memops.incr, 1);\n    generate_port(self.to_recv, proto.req(i));\n  }\n  fun void on_resp(t self, uint32 i, uint32 r) {\n    IntArray.setm(self.resp_ct, 0, memops.incr, 1);\n    printf("resp %d -> %d", i, r);\n  }\n}\n\nmodule receiver {\n  type t = { IntArray.t seen; port to_sender; };\n  comptime fun t create(port to_sender) {\n    return t { seen = IntArray.create(1); to_sender = to_sender; };\n  }\n  fun void on_req(t self, uint32 i) {\n    IntArray.setm(self.seen, 0, memops.incr, 1);\n    generate_port(self.to_sender, proto.resp(i, i + 1));\n  }\n}\n\nnode a {\n  port ctl = Port.create();\n  port link_b = Port.create();\n  global sender.t s = sender.create(link_b);\n  event start(uint32 i);\n  handle start(uint32 i) { sender.send_req(s, i); }\n  handle proto.resp(uint32 i, uint32 r) { sender.on_resp(s, i, r); }\n}\n\nnode b {\n  port link_a = Port.create();\n  port out = Port.create();\n  global receiver.t r = receiver.create(link_a);\n  handle proto.req(uint32 i) {\n    receiver.on_req(r, i);\n    if (i == 7) { generate_port(out, proto.req(i)); }\n  }\n}\n\nlink a.ctl -- external;\nlink a.link_b -- b.link_a;\nlink b.out --> external;\n'],[0,"source_counter.in",'# events, one per line: packets from source 1 and 2 arrive on port 0\n{"port": 0, "event": "packet", "args": [1, 9]}\n{"port": 0, "event": "packet", "args": [1, 9]}\n{"port": 0, "event": "packet", "args": [2, 9]}\n{"port": 0, "event": "packet", "args": [1, 9]}\n# a query from port 3: the count is printed and sent back out of port 3\n{"port": 3, "even