  // the event this mbuf carries\n\t%s out_events[%s]; // handler outputs (input mbuf only)\n\tuint16_t        n_out;                     // number of out_events filled\n\tuint32_t        payload_off;               // offset of the payload in the frame\n} qe_priv_t;\n\nstatic inline qe_priv_t *qe(struct rte_mbuf *m) { return (qe_priv_t *)rte_mbuf_to_priv(m); }\n\n// a packet view over the mbuf's data (single segment: rx drops multi-segment frames)\nstatic inline %s view_over(struct rte_mbuf *m) {\n\tuint8_t *d = rte_pktmbuf_mtod(m, uint8_t *);\n\treturn (%s){ .start = d, .cursor = d, .end = d + rte_pktmbuf_pkt_len(m), .bit_off = 0 };\n}\n\n/******** pipeline rings (DPDK rte_ring, single-producer / single-consumer) ********/\n#define RING_SIZE 1024\n#define BURST_SIZE 64   // max mbufs per rx call or recirc_in dequeue\n#define PORT_RECIRC %su  // out_event.port sentinel: recirculate, don't egress\n\n// A burst is the unit each stage processes; rx_in and tx_in carry burst pointers.\n// The pool rotates, which is safe single-threaded: tx_in is drained every iteration,\n// so at most one burst per port plus the recirculation burst is live at once.\ntypedef struct { unsigned n; struct rte_mbuf *m[BURST_SIZE]; } burst_t;\n#define N_BURSTS (RTE_MAX_ETHPORTS + 2)\nstatic burst_t bursts[N_BURSTS];\nstatic unsigned next_burst;\nstatic inline burst_t *burst_new(void) { burst_t *b = &bursts[next_burst++ %% N_BURSTS]; b->n = 0; return b; }\nstatic void burst_drop(burst_t *b, uint64_t *counter) { for (unsigned k = 0; k < b->n; k++) { (*counter)++; rte_pktmbuf_free(b->m[k]); } }\n\nstatic struct rte_ring *rx_in;      // burst_t*: parsed, awaiting the handler\nstatic struct rte_ring *recirc_in;  // mbuf*: recirculated, awaiting the handler (drop-tail)\nstatic struct rte_ring *tx_in;      // burst_t*: handled, awaiting output\n\n/******** counters, printed at exit ********/\nstatic struct {\n\tuint64_t rx, tx, recirc;                  // frames received / sent / recirculated\n\tuint